const sd = $getWorkflowStaticData('global');
const bot = $env.TELEGRAM_BOT_TOKEN;
const H = this.helpers;
const m = $input.first().json.message;
if (!m) { return []; }
const chatId0 = m.chat.id;
if (sd.editing && sd.editing[chatId0] && (m.text || m.caption)) {
  const pid = sd.editing[chatId0];
  const post = (sd.posts || {})[pid];
  delete sd.editing[chatId0];
  if (post) {
    post.caption = String(m.text || m.caption).trim();
    const fids = post.fileIds || [];
    if (fids.length === 1) { await H.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot}/sendPhoto`, body: { chat_id: chatId0, photo: fids[0] }, json: true }); }
    else if (fids.length > 1) { await H.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot}/sendMediaGroup`, body: { chat_id: chatId0, media: fids.slice(0, 10).map((id) => ({ type: 'photo', media: id })) }, json: true }); }
    const t = 'Обновлённый черновик:\n\n' + post.caption + '\n\nОпубликовать в Instagram?';
    await H.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot}/sendMessage`, body: { chat_id: chatId0, text: t, reply_markup: { inline_keyboard: [[{ text: 'Опубликовать', callback_data: 'approve:' + pid }, { text: 'Отредактировать', callback_data: 'edit:' + pid }, { text: 'Отклонить', callback_data: 'reject:' + pid }]] } }, json: true });
  }
  return [];
}
if (!m.photo) { return []; }
const gid = String(m.media_group_id || ('single_' + m.message_id));
if (!sd.groups) { sd.groups = {}; }
if (!sd.groups[gid]) { sd.groups[gid] = { fileIds: [], caption: '', chatId: m.chat.id, ts: Date.now(), done: false }; }
const g = sd.groups[gid];
const largest = m.photo[m.photo.length - 1];
g.fileIds.push(largest.file_id);
if (m.caption) { g.caption = m.caption; }
g.ts = Date.now();
return [{ json: { gid } }];

const sd = $getWorkflowStaticData('global');
const gid = $input.first().json.gid;
const g = (sd.groups || {})[gid];
if (!g) { return []; }
if (g.done) { return []; }
if (Date.now() - g.ts < 6500) { return []; }
g.done = true;
const out = { chatId: g.chatId, caption: g.caption, fileIds: g.fileIds };
delete sd.groups[gid];
return [{ json: out }];

const bot = $env.TELEGRAM_BOT_TOKEN;
const gk = $env.GEMINI_API_KEY;
const model = $env.GEMINI_MODEL || 'gemini-flash-latest';
const data = $input.first().json;
const fileIds = data.fileIds || [];
const chatId = data.chatId;
const userCaption = data.caption || '';
const H = this.helpers;
const parts = [];
const fileUrls = [];
let imgCount = 0;
for (const fid of fileIds) {
  const gf = await H.httpRequest({ method: 'GET', url: `https://api.telegram.org/bot${bot}/getFile`, qs: { file_id: fid }, json: true });
  const p = gf.result.file_path;
  const url = `https://api.telegram.org/file/bot${bot}/${p}`;
  fileUrls.push(url);
  if (imgCount < 5) {
    const bin = await H.httpRequest({ method: 'GET', url, encoding: 'arraybuffer' });
    const b64 = Buffer.from(bin).toString('base64');
    parts.push({ inline_data: { mime_type: 'image/jpeg', data: b64 } });
    imgCount++;
  }
}
const prompt = 'Ты SMM-специалист мастера корпусной мебели (кухни, шкафы, гардеробные) из Бишкека, Кыргызстан. По фото готовой работы напиши продающий пост для Instagram на русском языке: опиши стиль, материалы и преимущества, добавь 2-3 эмодзи, затем призыв подписаться и заказать мебель. В конце добавь 8-10 релевантных хештегов, обязательно включив локальные для Бишкека и Кыргызстана (например #Бишкек #Кыргызстан #мебельБишкек #кухниБишкек #шкафыБишкек #мебельназаказБишкек #Bishkek #Kyrgyzstan). Комментарий мастера: ' + userCaption + '. Верни только готовый текст поста без пояснений.';
parts.unshift({ text: prompt });
let caption = 'Не удалось сгенерировать описание.';
try {
  const gres = await H.httpRequest({ method: 'POST', url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${gk}`, body: { contents: [{ parts }] }, json: true });
  caption = (gres && gres.candidates && gres.candidates[0] && gres.candidates[0].content && gres.candidates[0].content.parts[0].text) ? gres.candidates[0].content.parts[0].text.trim() : caption;
} catch (e) {
  const desc = (e && e.response && e.response.body) ? JSON.stringify(e.response.body) : (e.message || 'unknown');
  caption = 'Ошибка ИИ: ' + desc + '. Комментарий: ' + userCaption;
}
if (caption.length > 2100) { caption = caption.slice(0, 2100); }
const sd = $getWorkflowStaticData('global');
if (!sd.posts) { sd.posts = {}; }
const postId = Date.now().toString(36);
sd.posts[postId] = { caption, fileUrls, fileIds, chatId };
return [{ json: { postId, caption, fileUrls, chatId, fileIds } }];

const bot = $env.TELEGRAM_BOT_TOKEN;
const H = this.helpers;
const d = $input.first().json;
const chatId = d.chatId;
const fileIds = d.fileIds || [];
const caption = d.caption;
const postId = d.postId;
async function tg(method, body) {
  try {
    return await H.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot}/${method}`, body, json: true });
  } catch (e) {
    const desc = (e && e.response && e.response.body) ? JSON.stringify(e.response.body) : (e.message || 'unknown');
    throw new Error(method + ' -> ' + desc);
  }
}
if (fileIds.length === 1) {
  await tg('sendPhoto', { chat_id: chatId, photo: fileIds[0] });
} else if (fileIds.length > 1) {
  const media = fileIds.slice(0, 10).map((id) => ({ type: 'photo', media: id }));
  await tg('sendMediaGroup', { chat_id: chatId, media });
}
const text = 'Черновик поста:\n\n' + caption + '\n\nОпубликовать в Instagram?';
await tg('sendMessage', { chat_id: chatId, text, reply_markup: { inline_keyboard: [[{ text: 'Опубликовать', callback_data: 'approve:' + postId }, { text: 'Отредактировать', callback_data: 'edit:' + postId }, { text: 'Отклонить', callback_data: 'reject:' + postId }]] } });
return [{ json: { ok: true } }];

const bot = $env.TELEGRAM_BOT_TOKEN;
const igUser = $env.IG_USER_ID;
const igToken = $env.IG_ACCESS_TOKEN;
const H = this.helpers;
const cq = $input.first().json.callback_query;
const chatId = cq.message.chat.id;
await H.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot}/answerCallbackQuery`, body: { callback_query_id: cq.id }, json: true });
try { await H.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot}/editMessageReplyMarkup`, body: { chat_id: cq.message.chat.id, message_id: cq.message.message_id, reply_markup: { inline_keyboard: [] } }, json: true }); } catch (e0) {}
const parts = String(cq.data || '').split(':');
const action = parts[0];
const postId = parts[1];
const sd = $getWorkflowStaticData('global');
const post = (sd.posts || {})[postId];
if (!post) {
  await H.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot}/sendMessage`, body: { chat_id: chatId, text: 'Данные поста не найдены (устарели). Отправьте фото заново.' }, json: true });
  return [{ json: { ok: false } }];
}
if (action === 'reject') {
  delete sd.posts[postId];
  await H.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot}/sendMessage`, body: { chat_id: chatId, text: '❌ Публикация отменена.' }, json: true });
  return [{ json: { ok: true } }];
}
if (action === 'edit') {
  if (!sd.editing) { sd.editing = {}; }
  sd.editing[chatId] = postId;
  await H.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot}/sendMessage`, body: { chat_id: chatId, text: '✏️ Пришлите новый текст поста одним сообщением — я обновлю черновик.' }, json: true });
  return [{ json: { ok: true } }];
}
const graph = 'https://graph.facebook.com/v21.0';
try {
  let creationId;
  if (post.fileUrls.length === 1) {
    const c = await H.httpRequest({ method: 'POST', url: `${graph}/${igUser}/media`, body: { image_url: post.fileUrls[0], caption: post.caption, access_token: igToken }, json: true });
    creationId = c.id;
  } else {
    const children = [];
    for (const u of post.fileUrls.slice(0, 10)) {
      const ch = await H.httpRequest({ method: 'POST', url: `${graph}/${igUser}/media`, body: { image_url: u, is_carousel_item: true, access_token: igToken }, json: true });
      children.push(ch.id);
    }
    const car = await H.httpRequest({ method: 'POST', url: `${graph}/${igUser}/media`, body: { media_type: 'CAROUSEL', children: children.join(','), caption: post.caption, access_token: igToken }, json: true });
    creationId = car.id;
  }
  const pub = await H.httpRequest({ method: 'POST', url: `${graph}/${igUser}/media_publish`, body: { creation_id: creationId, access_token: igToken }, json: true });
  delete sd.posts[postId];
  await H.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot}/sendMessage`, body: { chat_id: chatId, text: 'Опубликовано в Instagram. ID: ' + pub.id }, json: true });
  return [{ json: { ok: true, id: pub.id } }];
} catch (e) {
  const emsg = (e && e.response && e.response.body) ? JSON.stringify(e.response.body) : (e.message || 'unknown');
  await H.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot}/sendMessage`, body: { chat_id: chatId, text: 'Ошибка публикации: ' + emsg }, json: true });
  return [{ json: { ok: false, error: emsg } }];
}
